import * as ddb from "@aws-sdk/client-dynamodb";
import {marshall} from "@aws-sdk/util-dynamodb";
import {KeySchema, TableType, SchemaType, ExpressionGenerator, FilterConditionGenerator} from "./schema";
import {prepareCommand} from "./util";
import _ from "lodash";

/**
 * DynamoDb {@link ddb.ScanCommandInput} for a given {@link Table}
 */
interface ScanCommand<Table, V> {
    /**
     * See {@link ddb.ScanInput.IndexName}
     */
    indexName?: string
    /**
     * Context values to be used in expressions generated by {@link filter}.
     */
    values?: V
    /**
     * Function generating {@link ddb.ScanInput.FilterExpression}
     */
    filter?: FilterConditionGenerator<Table, V>
    /**
     * Function generating {@link ddb.ScanInput.ProjectionExpression}
     */
    projection?: ExpressionGenerator<Table, never>
    /**
     * See {@link ddb.ScanInput.Select}
     */
    select?: ddb.Select
    /**
     * See {@link ddb.ScanInput.Limit}
     */
    limit?: number
    /**
     * See {@link ddb.ScanInput.ExclusiveStartKey}
     */
    exclusiveStartKey?: SchemaType<KeySchema<Table>>,
    /**
     * See {@link ddb.ScanInput.Segment}
     */
    segment?: number,
    /**
     * See {@link ddb.ScanInput.TotalSegments}
     */
    totalSegments?: number,
    /**
     * See {@link ddb.ScanInput.ConsistentRead}
     */
    consistentRead?: boolean
    /**
     * See {@link ddb.ScanInput.ReturnConsumedCapacity}
     */
    returnConsumedCapacity?: ddb.ReturnConsumedCapacity
}

/**
 * Create {@link ddb.ScanCommandInput}.
 * @param tbl - target table
 * @param command - command parameters
 */
export function scan<T extends TableType<T>, V>(tbl: T, command: ScanCommand<T, V>): ddb.ScanCommandInput {
    const {
        attributeNames,
        attributeValues,
        key,
        attr,
        val
    } = prepareCommand(tbl, command.values as NonNullable<V>);
    const {filter, projection} = command

    return {
        TableName: tbl.name,
        IndexName: command.indexName,
        ProjectionExpression: projection?.({key, attr, val}),
        FilterExpression: filter?.({attr, val}),
        Select: command.select,
        Limit: command.limit,
        ExclusiveStartKey: command.exclusiveStartKey !== undefined ? marshall(command.exclusiveStartKey) : undefined,
        Segment: command.segment,
        TotalSegments: command.totalSegments,
        ConsistentRead: command.consistentRead,
        ReturnConsumedCapacity: command.returnConsumedCapacity,
        ExpressionAttributeNames: !_.isEmpty(attributeNames) ? attributeNames : undefined,
        ExpressionAttributeValues: !_.isEmpty(attributeValues) ? attributeValues : undefined,
    };
}

/**
 * Create {@link ddb.ScanCommand}.
 * @param tbl - target table
 * @param command - command parameters
 */
export function scanCommand<T extends TableType<T>, V>(tbl: T, command: ScanCommand<T, V>): ddb.ScanCommand {
    return new ddb.ScanCommand(scan(tbl, command))
}